    if ((par = ast_newpar(ast)) < 0)
        return -1;
    if ((node = ast_newnode(ast)) < 0)
        return -1;
    ast->par[par] = node;
    ast->nodes[node] = (ast_node_t){rulename, from, 0, 0, 0};
    return par;
}

functions.ast_close:
int32_t ast_close(ast_t ast, astnode_t to, astnode_t open)
{
    ast_node_t *nd;
    astnode_t par;
    if (open < 0)
        return -1;
    nd = &ast->nodes[ast->par[open]];
    if (ast->fail)
    {
        ast->pos = nd->from;
        ast->nodes_cnt = ast->par[open];
        ast->par_cnt = open;
        return -1;
    }
    if ((par = ast_newpar(ast)) < 0)
        return -1;
    nd->to = to;
    nd->delta = par - open;
    nd->tag = 0;
    ast->par[par] = -(nd->delta);
    ast->cur_node = par;
    ast->cur_rule = nd->rule;
    return par;
}

functions.astnewinfo:
void astnewinfo(ast_t ast, int32_t info)
{
    astnode_t par;
    if (!ast->fail)
    {
        par = ast_open(ast, ast->pos, skp_N__INFO);
        ast_close(ast, ast->pos, par);
        ast->nodes[ast->par[par]].tag = info;
        ast->lastinfo = info;
    }
}

functions.astnodeinfo:
int32_t astnodeinfo(ast_t ast, astnode_t node)
{
    if (!ast || node >= ast->par_cnt || node < 0)
        return 0;
    if (ast->par[node] < 0)
        node += ast->par[node];
    return ast->nodes[ast->par[node]].tag;
}

functions.ast_setinfo:
void ast_setinfo(ast_t ast, int32_t info, astnode_t node)
{
    if (!ast || ast->par_cnt <= node)
        return;
    if (node == -1)
        node = ast->par_cnt - 1;
    ;
    if (ast->par[node] < 0)
        node += ast->par[node];
    ast->nodes[ast->par[node]].tag = info;
}

functions.astprintsexpr:
void astprintsexpr(ast_t ast, FILE *f)
{
    int32_t node = -1;
    while ((node = astnextdf(ast, node)) != -1)
    {
        if (astisnodeentry(ast, node))
        {
            fprintf(f, "(%s ", astnoderule(ast, node));
            if (astisleaf(ast, node))
            {
                fputc('\'', f);
                if (astnoderule(ast, node) == skp_N__INFO)
                {
                    fprintf(f, "%d", astnodeinfo(ast, node));
                }
                else
                    for (char *s = astnodefrom(ast, node); s < astnodeto(ast, node); s++)
                    {
                        if (*s == '\'')
                            fputc('\\', f);
                        fputc(*s, f);
                    }
                fputc('\'', f);
            }
        }
        else
            fputc(')', f);
    }
}

functions.astprinttree:
void astprinttree(ast_t ast, FILE *f)
{
    int32_t node = -1;
    int32_t levl = 0;
    int32_t tag = 0;
    while ((node = astnextdf(ast, node)) != -1)
    {
        if (astisnodeentry(ast, node))
        {
            for (int k = 0; k < levl; k += 4)
                fputs("    ", f);
            fprintf(f, "[%s", astnoderule(ast, node));
            tag = astnodeinfo(ast, node);
            if (tag != 0)
                fprintf(f, " (%d)", tag);
            fputc(']', f);
            levl += 4;
            if (astisleaf(ast, node))
            {
                fputc(' ', f);
                fputc('\'', f);
                for (char *s = astnodefrom(ast, node); s < astnodeto(ast, node); s++)
                {
                    if (*s == '\'')
                        fputc('\\', f);
                    fputc(*s, f);
                }
                fputc('\'', f);
            }
            fputc('\n', f);
        }
        else
            levl -= 4;
    }
}

functions.skp__abort:
void skp__abort(ast_t ast, char *msg, char *rule)
{
    if (msg != (char *)0)
        ast->err_msg = msg;
    ast->err_pos = ast->pos;
    ast->err_rule = rule;
    longjmp(ast->jbuf, 1);
}
